271	import org.springframework.batch.core.SkipListener;
272	import org.springframework.batch.core.Step;
273	import org.springframework.batch.core.configuration.annotation.StepScope;
274	import org.springframework.batch.core.job.builder.JobBuilder;
275	import org.springframework.batch.core.repository.JobRepository;
276	import org.springframework.batch.core.step.builder.StepBuilder;
277	import org.springframework.batch.item.ItemProcessor;
278	import org.springframework.batch.item.database.JpaItemWriter;
279	import org.springframework.batch.item.database.JpaPagingItemReader;
280	import org.springframework.batch.item.database.builder.JpaPagingItemReaderBuilder;
