551	import lombok.RequiredArgsConstructor;
552	import org.springframework.batch.core.Job;
553	import org.springframework.batch.core.JobParameters;
554	import org.springframework.batch.core.JobParametersBuilder;
555	import org.springframework.batch.core.launch.JobLauncher;
556	import org.springframework.beans.factory.annotation.Autowired;
557	import org.springframework.beans.factory.annotation.Qualifier;
558	import org.springframework.scheduling.annotation.Scheduled;
559	import org.springframework.stereotype.Component;
560	
561	@Component
562	@RequiredArgsConstructor
563	public class ShipmentBatchScheduler {
564	
565	    private final JobLauncher jobLauncher;
566	
567	    @Qualifier("updateShipmentStatusesJob")
568	    @Autowired
569	    private Job updateShipmentStatusesJob;
570	
571	//    private final Job updateShipmentStatusesJob;
572	//
573	//    // Write the constructor manually:
574	//    public ShipmentBatchScheduler(
575	//            JobLauncher jobLauncher,
576	//            @Qualifier("updateShipmentStatusesJob") Job updateShipmentStatusesJob
577	//    ) {
578	//        this.jobLauncher = jobLauncher;
579	//        this.updateShipmentStatusesJob = updateShipmentStatusesJob;
580	//    }
581	
582	    @Scheduled(cron = "0 0 */6 * * *")
583	    public void scheduleShipmentStatusJob() {
584	        try {
585	            JobParameters jobParameters = new JobParametersBuilder()
586	                    .addLong("timestamp", System.currentTimeMillis())
587	                    .toJobParameters();
588	            jobLauncher.run(updateShipmentStatusesJob, jobParameters);
589	        } catch (Exception e) {
590	            e.printStackTrace();
591	        }
592	    }
593	}
